from collections import defaultdict

def test():
    rslt = defaultdict(list)
    inputs = {"easy": [[1, 1], [3, 4]], "hard": [[1234, -232], [123.21, 21.31]]}

    for k in inputs:
        for i in inputs[k]:
            rslt[k].append(sum(i))

    return dict(rslt)
```

