You just need to inherit from sklearn.base.BaseEstimator as well as the TransformerMixin. This will ensure that your custom transformer is recognized as a valid scikit-learn estimator. The code below demonstrates the necessary adjustments.

```python
import numpy as np
import sklearn
from sklearn.compose import TransformedTargetRegressor
from sklearn.linear_model import LinearRegression

class MyTransform(sklearn.base.BaseEstimator, sklearn.base.TransformerMixin):
    def fit(self, *_, **__):
        return self

    def transform(self, X):
        return np.array(X) * 10

    def inverse_transform(self, X):
        return np.array(X) / 10

def MyLinearRegression():
    return TransformedTargetRegressor(
        regressor=LinearRegression(),
        transformer=MyTransform()
    )

def test():
    model = MyLinearRegression()
    model.fit(X=[[1], [2], [3]], y=[1, 2, 3])
    predictions = model.predict([[4], [5]])
    print(predictions)  # Output transformed predictions
```

